  $('copyCodeBtn').addEventListener('click',copyCode);$('copyTransferCodeBtn').addEventListener('click',copyCode);$('copyInviteLinkBtn').addEventListener('click',copyInviteLink);$('copyTransferInviteLinkBtn').addEventListener('click',copyInviteLink);document.querySelectorAll('[data-home]').forEach(b=>b.addEventListener('click',()=>{if(state.code)leaveSession();else showView('homeView');}));document.querySelectorAll('[data-session-action]').forEach(b=>b.addEventListener('click',leaveSession));document.querySelectorAll('[data-end]').forEach(b=>b.addEventListener('click',()=>{clearLastRoom();if(state.ws&&state.ws.readyState===WebSocket.OPEN)signal({type:'leave'});resetSession('Cancelled joining.');}));$('chooseFilesBtn').addEventListener('click',()=>$('fileInput').click());$('chooseFilesQuickBtn').addEventListener('click',()=>$('fileInput').click());$('fileInput').addEventListener('change',e=>{sendFiles(e.target.files);e.target.value='';});$('downloadAllBtn').addEventListener('click',downloadAllReceived);function setTransferView(mode,persist=true){const tiles=mode==='tiles';$('transferList').classList.toggle('tiles',tiles);$('listViewBtn').setAttribute('aria-pressed',String(!tiles));$('tileViewBtn').setAttribute('aria-pressed',String(tiles));if(persist)try{localStorage.setItem('drop.transferView',tiles?'tiles':'list');}catch{}}$('listViewBtn').addEventListener('click',()=>setTransferView('list'));$('tileViewBtn').addEventListener('click',()=>setTransferView('tiles'));try{setTransferView(localStorage.getItem('drop.transferView')||'list',false);}catch{setTransferView('list',false);}const zone=$('dropZone');['dragenter','dragover'].forEach(n=>zone.addEventListener(n,e=>{e.preventDefault();zone.classList.add('dragging');}));['dragleave','drop'].forEach(n=>zone.addEventListener(n,e=>{e.preventDefault();zone.classList.remove('dragging');}));zone.addEventListener('drop',e=>sendFiles(e.dataTransfer.files));
