  $('pasteHint').addEventListener('click',async()=>{primeAudio();if(!navigator.clipboard?.read){toast('Use Ctrl+V (or ⌘+V) to paste a copied image or file.');return;}try{const items=await navigator.clipboard.read();const files=[];for(const item of items){for(const type of item.types){if(type==='text/plain')continue;const blob=await item.getType(type);files.push(new File([blob],`pasted-${Date.now()}.${(type.split('/')[1]||'bin').replace(/[^a-z0-9.+-]/gi,'')}`,{type}));}}if(files.length)sendFiles(files);else toast('No file or image found in the clipboard.');}catch{toast('Clipboard access was blocked. Copy a file or image and use Ctrl+V instead.');}});
