  function stopQrScanner(){if(scanWinkTimer){clearTimeout(scanWinkTimer);scanWinkTimer=0;}const wink=$('scannerDesktopWink');if(wink)wink.classList.remove('wink-visible');if(scanRaf)cancelAnimationFrame(scanRaf);scanRaf=0;scanBusy=false;if(scanStream){for(const track of scanStream.getTracks())track.stop();scanStream=null;}const video=$('scanQrVideo');if(video)video.srcObject=null;const modal=$('scanQrModal');if(modal){modal.classList.add('hidden');modal.setAttribute('aria-hidden','true');}scanDetector=null;scanLastValue='';}
  function ensureJsQr(){if(typeof window.jsQR==='function')return Promise.resolve(true);if(scanLibPromise)return scanLibPromise;scanLibPromise=new Promise(resolve=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js';script.async=true;script.onload=()=>resolve(typeof window.jsQR==='function');script.onerror=()=>resolve(false);document.head.append(script);});return scanLibPromise;}
  function getDropCodeFromQr(raw){const value=String(raw||'').trim();if(/^[A-Z0-9]{6}$/i.test(value))return value.toUpperCase();try{const url=new URL(value);if(url.protocol!=='https:'&&url.origin!==location.origin)return '';if(url.origin!==location.origin&&url.hostname!=='drop-snowy.vercel.app')return '';const code=(url.searchParams.get('join')||'').toUpperCase().replace(/[^A-Z0-9]/g,'');return /^[A-Z0-9]{6}$/.test(code)?code:'';}catch{return '';}}
  async function startQrScanner(){stopQrScanner();const modal=$('scanQrModal'),video=$('scanQrVideo'),status=$('scanQrStatus'),retry=$('scanQrRetryBtn'),wink=$('scannerDesktopWink');if(wink&&window.matchMedia('(min-width:700px) and (hover:hover) and (pointer:fine)').matches){const variants=['Caught you looking 👀 For the easiest scan, use your phone’s rear camera.','Looking good 😎 Now point a phone’s rear camera at the room QR.','Plot twist: your webcam sees you too. 📸 A phone camera may be easier for this QR.','A face reveal already? 👀 Try scanning this QR with your phone’s rear camera.','Webcam check ✅ For a smoother join, scan the room QR from your phone.'];wink.textContent=variants[Math.floor(Math.random()*variants.length)];scanWinkTimer=setTimeout(()=>{if(!modal.classList.contains('hidden'))wink.classList.add('wink-visible');scanWinkTimer=0;},1000);}modal.classList.remove('hidden');modal.setAttribute('aria-hidden','false');status.textContent='Starting camera…';status.classList.remove('scanner-status-error');retry.classList.add('hidden');if(!navigator.mediaDevices?.getUserMedia){status.textContent='Camera scanning is unavailable in this browser. Use Join with a code instead.';status.classList.add('scanner-status-error');retry.classList.remove('hidden');return;}try{scanStream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});if(modal.classList.contains('hidden')){for(const track of scanStream.getTracks())track.stop();scanStream=null;return;}video.srcObject=scanStream;await video.play();scanCanvas=document.createElement('canvas');scanCanvas.width=640;scanCanvas.height=480;scanContext=scanCanvas.getContext('2d',{willReadFrequently:true});if('BarcodeDetector'in window){try{const supported=await window.BarcodeDetector.getSupportedFormats();if(supported.includes('qr_code'))scanDetector=new window.BarcodeDetector({formats:['qr_code']});}catch{scanDetector=null;}}if(!scanDetector){status.textContent='Point at the QR code — scanning automatically';const loaded=await ensureJsQr();if(!loaded){status.textContent='QR scanner could not load. Check your connection or join with a code.';status.classList.add('scanner-status-error');retry.classList.remove('hidden');return;}}status.textContent='Point at the QR code — scanning automatically';scanRaf=requestAnimationFrame(scanQrFrame);}catch(error){console.error('Camera scanner failed:',error);if(scanStream){for(const track of scanStream.getTracks())track.stop();scanStream=null;}video.srcObject=null;status.textContent=error?.name==='NotAllowedError'?'Camera permission was denied. Allow camera access, then try again.':'Could not start the camera. Check camera access or join with a code.';status.classList.add('scanner-status-error');retry.classList.remove('hidden');}}
  async function scanQrFrame(){scanRaf=0;if(!scanStream||$('scanQrModal').classList.contains('hidden'))return;scanRaf=requestAnimationFrame(scanQrFrame);if(scanBusy)return;const video=$('scanQrVideo');if(video.readyState<2||!video.videoWidth)return;scanBusy=true;try{let raw='';if(scanDetector){try{const found=await scanDetector.detect(video);if(found.length)raw=found[0].rawValue||'';}catch(error){console.debug('Native QR detection failed; switching to jsQR.',error);scanDetector=null;const loaded=await ensureJsQr();if(!loaded){const status=$('scanQrStatus');status.textContent='QR decoding failed to start. Check your connection or join with a code.';status.classList.add('scanner-status-error');$('scanQrRetryBtn').classList.remove('hidden');}}}if(!scanDetector&&!raw&&scanContext&&typeof window.jsQR==='function'){const width=640,height=Math.max(1,Math.round(video.videoHeight*width/video.videoWidth));if(scanCanvas.width!==width||scanCanvas.height!==height){scanCanvas.width=width;scanCanvas.height=height;}scanContext.drawImage(video,0,0,width,height);const pixels=scanContext.getImageData(0,0,width,height);const result=window.jsQR(pixels.data,width,height,{inversionAttempts:'dontInvert'});if(result)raw=result.data||'';}if(raw){const code=getDropCodeFromQr(raw);if(code){closeQrScanner();setJoinPanel(false);setCodeInput(code);toast('QR detected. Joining room…');joinSession();return;}const status=$('scanQrStatus');if(raw!==scanLastValue){scanLastValue=raw;status.textContent='That QR is not a drop. room invite. Keep scanning or use a session code.';}}}catch(error){console.debug('QR scan frame skipped.',error);}finally{scanBusy=false;}}
  function closeQrScanner(){stopQrScanner();}
  function applyTheme(theme,persist=true){
    const chosen=theme==='dark'?'dark':'light';
    document.documentElement.dataset.theme=chosen;
    const toggle=$('themeToggle'),icon=$('themeIcon');
    if(toggle){toggle.setAttribute('aria-label',chosen==='dark'?'Switch to light mode':'Switch to dark mode');toggle.setAttribute('title',chosen==='dark'?'Switch to light mode':'Switch to dark mode');}
    if(icon){icon.querySelectorAll('[data-theme-icon]').forEach(node=>{const active=node.getAttribute('data-theme-icon')===(chosen==='dark'?'light':'dark');node.hidden=!active;node.style.display=active?'block':'none';});}
    const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',chosen==='dark'?'#171916':'#f8f8f6');
    if(persist)try{localStorage.setItem('drop.theme',chosen);}catch{}
  }
